// Domain models for the Urdu–English AI Dictionary feature.

enum DictionaryResultSource {
  /// Returned from the curated backend database.
  database,

  /// Generated by the server-side AI provider.
  ai,
}

/// A single example sentence pair.
class DictionaryExample {
  const DictionaryExample({required this.english, required this.urdu});

  final String english;
  final String urdu;

  factory DictionaryExample.fromJson(Map<String, dynamic> json) {
    return DictionaryExample(
      english: json['english'] as String? ?? '',
      urdu: json['urdu'] as String? ?? '',
    );
  }

  Map<String, dynamic> toJson() => {'english': english, 'urdu': urdu};
}

/// A full dictionary lookup result.
class DictionaryResult {
  const DictionaryResult({
    required this.query,
    required this.source,
    required this.englishWord,
    required this.urduMeaning,
    required this.simpleDefinition,
    required this.partOfSpeech,
    required this.examples,
    this.pronunciationText,
  });

  final String query;
  final DictionaryResultSource source;
  final String englishWord;
  final String urduMeaning;
  final String simpleDefinition;
  final String partOfSpeech;
  final List<DictionaryExample> examples;

  /// Text to pass to TTS (defaults to [englishWord] when null).
  final String? pronunciationText;

  String get ttsText => pronunciationText ?? englishWord;

  factory DictionaryResult.fromJson(Map<String, dynamic> json) {
    final sourceStr = json['source'] as String? ?? 'ai';
    final source = sourceStr == 'database'
        ? DictionaryResultSource.database
        : DictionaryResultSource.ai;

    final rawExamples = json['examples'];
    final List<DictionaryExample> examples;
    if (rawExamples is List) {
      examples = rawExamples
          .whereType<Map<String, dynamic>>()
          .map(DictionaryExample.fromJson)
          .toList();
    } else {
      examples = const [];
    }

    return DictionaryResult(
      query: json['query'] as String? ?? '',
      source: source,
      englishWord: json['englishWord'] as String? ?? '',
      urduMeaning: json['urduMeaning'] as String? ?? '',
      simpleDefinition: json['simpleDefinition'] as String? ?? '',
      partOfSpeech: json['partOfSpeech'] as String? ?? '',
      examples: examples,
      pronunciationText: json['pronunciationText'] as String?,
    );
  }
}

/// Carries the result of a dictionary lookup or an error description.
sealed class DictionaryLookupState {
  const DictionaryLookupState();
}

class DictionaryIdle extends DictionaryLookupState {
  const DictionaryIdle();
}

class DictionaryLoading extends DictionaryLookupState {
  const DictionaryLoading();
}

class DictionarySuccess extends DictionaryLookupState {
  const DictionarySuccess(this.result);
  final DictionaryResult result;
}

class DictionaryError extends DictionaryLookupState {
  const DictionaryError(
    this.message, {
    this.isOffline = false,
    this.aiUnavailable = false,
  });
  final String message;
  final bool isOffline;
  final bool aiUnavailable;
}

class DictionaryEmpty extends DictionaryLookupState {
  const DictionaryEmpty(this.query);
  final String query;
}
